window.AUTH=window.AUTH||{};window.AUTH["21-454"]={"d":"21-454","id":"2022/21-454","n":"Sackett v. Environmental Protection Agency","briefs":[{"k":"petitioner","label":"Brief of petitioners Michael Sackett, et al.","date":"2022-04-11","url":"https://www.supremecourt.gov/DocketPDF/21/21-454/220716/20220411143433423_FINAL%20Sackett%20Opening%20Brief.pdf","side":"pet","n":98},{"k":"respondent","label":"Brief of respondents U.S. Environmental Protection Agency, et al.","date":"2022-06-10","url":"https://www.supremecourt.gov/DocketPDF/21/21-454/227721/20220610173641467_21-454bsUnitedStates.pdf","side":"res","n":56},{"k":"reply","label":"Reply of petitioners Michael Sackett, et al.","date":"2022-07-08","url":"https://www.supremecourt.gov/DocketPDF/21/21-454/229685/20220708135220072_Sackett%20Reply%20Brief%20Merits%20-%20Final.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us2r28_hgcj.pdf","tr":true,"items":[{"t":"case","label":"Ass’n of Bituminous Contractors, Inc. v. Apfel","cite":"156 F.3d 1246","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/156/1246/","by":{"0":"48-49"}},{"t":"case","label":"Chevron, U.S.A., Inc. v. Natural Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"13","1":"38","2":"21"}},{"t":"case","label":"City of Milwaukee v. Illinois & Michigan","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"op":1,"sum":"In original proceedings brought by respondent State of Illinois, alleging that petitioners-the city of Milwaukee, its Sewerage Commission, and Milwaukee County's Metropolitan Sewerage Commission-and other Wisconsin cities were polluting Lake Michigan because of overflows of untreated sewage from their sewer systems and discharges of inadequately treated sewage from their treatment plants, this Court recognized the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","1":"2, 4, 5, 48"}},{"t":"case","label":"Cooley v. FERC","cite":"843 F.2d 1464","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/843/1464/","by":{"0":"37"}},{"t":"case","label":"County of Maui v. Haw. Wildlife Fund","cite":"140 S. Ct. 1462","y":2020,"id":"2019/18-260","sc":1,"op":1,"ar":4,"sum":"The Court held the Clean Water Act requires a permit when pollutants originate from a point source but are conveyed to navigable waters by a nonpoint source, such as groundwater, if the conveyance is the \"functional equivalent\" of a direct discharge.","sumSrc":"Oyez","by":{"0":"42, 46","1":"36","2":"11, 13, 22"}},{"t":"case","label":"Economy Light & Power Co. v. United States","cite":"256 U.S. 113","y":1921,"id":"scdb/1920-132","sc":1,"op":4,"sum":"_L_Artificial obstructions subject to abatement by public authority do not render non-navigable' in law a stream which in its natural state would be navigable iniact.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"32, 35"}},{"t":"case","label":"EPA v. California ex rel. State Water Res. Control Bd.","cite":"426 U.S. 200","y":1976,"id":"1975/74-1435","sc":1,"op":3,"sum":"While federal installations discharging water pollutants are obliged, under § 313 of the Federal Water Pollution Control Act Amendments of 1972 (Amendments), to comply to the same extent as nonfederal facilities with state \"requirements respecting control and abatement of pollution,\" obtaining a permit from a State with a federally approved permit program is not among such requirements. Federal installations are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","1":"4, 48"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Gwaltney of Smithfield, Ltd. v. Chesapeake Bay Found., Inc.","cite":"484 U.S. 49","y":1987,"id":"1987/86-473","sc":1,"sum":"Section 505(a) of the Clean Water Act authorizes private citizens to commence a civil action for injunctive relief and/or the imposition of civil penalties in federal district court against any person \"alleged to be in violation\" of the conditions of a National Pollutant Discharge Elimination System (NPDES) permit. Between 1981 and 1984, petitioner repeatedly violated the conditions of its NPDES permit by exceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"Hardy Salt Co. v. So. Pac. Transp. Co.","cite":"501 F.2d 1156","y":1974,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/501/1156/","op":2,"sum":"Noting that Congress only departs from the expanded Daniel Ball test by using “clear and explicit language,” as it did in parts of the Federal Power Act.","sumSrc":"opinion","by":{"0":"43"}},{"t":"case","label":"Holmes v. Secs. Investor Protection Corp.","cite":"503 U.S. 258","y":1992,"id":"1991/90-727","sc":1,"sum":"SIPC has demonstrated no right to sue Holmes under § 1964(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Hall v. Hall","cite":"138 S. Ct. 1118","y":2018,"id":"2017/16-1150","sc":1,"sum":"The Court decided that when one of multiple cases consolidated under FRCP 42(a) is finally decided, that ruling confers upon the losing party the right to immediate appeal regardless of whether any of the other consolidated cases are still pending.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Knick v. Township of Scott","cite":"139 S. Ct. 2162","y":2019,"id":"2018/17-647","sc":1,"sum":"A government violates the Takings Clause when it takes property without compensation, and a property owner may bring a Fifth Amendment claim under 42 U. S. C. §1983 at that time; the state-litigation requirement of Williamson County Regional Planning Comm’n v. Hamilton Bank of Johnson City, 473 U. S. 172, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"49"}},{"t":"case","label":"Marks v. United States","cite":"430 U.S. 188","y":1977,"id":"1976/75-708","sc":1,"sum":"The Due Process Clause of the Fifth Amendment precludes retroactive application to petitioners of the Miller standards, to the extent that those standards may impose criminal liability for conduct not punishable under the standards announced in Memoirs v. Massachusetts, 383 U. S. 413. Bouie v. City of Columbia, 378 U. S. 347. Specifically, petitioners are entitled to jury instructions requiring the jury to acquit …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Minnehaha Creek Watershed Dist. v. Hoffman","cite":"597 F.2d 617","y":1979,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/597/617/","by":{"0":"43"}},{"t":"case","label":"Natural Res. Def. Council, Inc. v. Callaway","cite":"392 F. Supp. 685","y":1975,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./392/685/","op":2,"by":{"0":"11","1":"6"}},{"t":"case","label":"Nichols v. United States","cite":"511 U.S. 738","y":1994,"id":"1993/92-8556","sc":1,"op":1,"sum":"After petitioner Nichols pleaded guilty to federal felony drug charges, he was assessed criminal history points under the United States Sentencing Guidelines, including one point for a state misdemeanor conviction for driving while under the influence (DUI), for which he was fined but not incarcerated. That point increased the maximum sentence of imprisonment from 210 to 235 months. Petitioner objected to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Oklahoma ex rel. Phillips v. Guy F. Atkinson Co.","cite":"313 U.S. 508","y":1941,"id":"scdb/1940-065","sc":1,"op":5,"sum":"1. The Denison Dam and Reservoir Project on the Red River in Oklahoma and Texas, authorized by the Act of June 28, 1938, is a valid exercise of the commerce power by Congress. P. 516. This is a multi-purpose project-part of a comprehensive scheme for controlling floods in the Mississippi River through reservoir control of its tributaries, of which the Red River is one of the more important. It aims also to protect …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"op":24,"sum":"The plurality rejected the argument that only actually-navigable waters can be regulated by the Clean Water Act, but also held that the word \"navigable\" in the Act cannot be divested of all meaning. The plurality held that the definitional term \"waters of the United States\" can only refer to \"relatively permanent, standing or flowing bodies of water,\" not \"occasional,\" \"intermittent,\" or \"ephemeral\" flows.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"op":4,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"S.D. Warren Co. v. Maine Bd. of Envtl. Protection","cite":"547 U.S. 370","y":2006,"id":"2005/04-1527","sc":1,"op":19,"sum":"The Supreme Court held that the term \"discharge\" in section 401 had historically been given a broad meaning by FERC, the Environmental Protection Agency, and even the Supreme Court. Justice David Souter, in the Opinion of the Court, wrote that \"[w]hen it applies to water, 'discharge' commonly means a 'flowing or issuing out.' .","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Sackett v. EPA","cite":"566 U.S. 120","y":2012,"id":"2011/10-1062","sc":1,"op":4,"sum":"The Court found that homeowners have a right to go to court over a Clean Water Act order of the Environmental Protection Agency.","sumSrc":"Oyez","by":{"0":"20-21","2":"23"}},{"t":"case","label":"Sackett v. EPA","cite":"622 F.3d 1139","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/622/1139/","by":{"0":"21"}},{"t":"case","label":"Sanitary Dist. of Chicago v. United States","cite":"266 U.S. 405","y":1925,"id":"scdb/1924-180","sc":1,"sum":"1. A suit to enjoin an agency of the State of Illinois from continuing diversions of water from Lake Michigan which lower that lake and threaten the like effect upon other lakes and connecting waters of the Great Lake System, including the St. Lawrence, is maintainable by the United States not only to remove obstruction to interstate and foreign commerce, but also to carry out treaty obligations to a foreign power. …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"35","2":"16-17"}},{"t":"case","label":"Solid Waste Agency of N. Cook County v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"op":20,"sum":"Recognizing that Riverside Bayview “held that the Corps had . . . jurisdiction over wetlands that actually abutted on a navigable waterway”.","sumSrc":"opinion","by":{"0":"passim","1":"7, 8, 26, 27, 28, 33","2":"1, 5-10, 14"}},{"t":"case","label":"U.S. Army Corps of Eng’rs v. Hawkes Co., Inc.","cite":"578 U.S. 590","y":2016,"id":"2015/15-290","sc":1,"op":5,"sum":"The Court determined that the Army Corps of Engineers’ jurisdictional determination that a property constituted “water of the United States” was a final agency action subject to judicial review under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"0":"10, 48"}},{"t":"case","label":"United States v. Appalachian Elec. Power Co.","cite":"311 U.S. 377","y":1940,"id":"scdb/1940-004","sc":1,"op":8,"sum":"1. Upon review of a case involving the scope of the federal commerce power in relation to licensing by the Federal Power Commission of a hydroelectric dam, this Court may determine for itself whether a particular waterway is a navigable water of the United States, and it is not precluded by the rule that factual findings concurred in by two courts below will be accepted here unless clear error is shown.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 35"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"op":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"United States v. Esso Standard Oil Co. of Puerto Rico","cite":"375 F.2d 621","y":1967,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/375/621/","by":{"0":"36"}},{"t":"case","label":"United States v. Hercules, Inc., Sunflower Army Ammunition Plant, Lawrence, Kan.","cite":"335 F. Supp. 102","y":1971,"court":"D. Kan.","url":"https://www.courtlistener.com/c/F.%20Supp./335/102/","by":{"0":"36"}},{"t":"case","label":"United States v. Johnson","cite":"467 F.3d 56","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/467/56/","by":{"0":"48"}},{"t":"case","label":"United States v. Lopez","cite":"514 U.S. 549","y":1995,"id":"1994/93-1260","sc":1,"op":3,"sum":"The Court found the 1990 Gun-Free School Zones Act unconstitutional for overstepping the congressional boundaries of the Commerce Clause.","sumSrc":"Oyez","by":{"0":"29","1":"38"}},{"t":"case","label":"United States v. Republic Steel Corp.","cite":"362 U.S. 482","y":1960,"id":"1959/56","sc":1,"op":1,"sum":"The Supreme Court held that the deposits were an obstruction within the meaning of the act and were not exempt. The Court also held that the district court was authorized to issue an injunction against the steel companies. Justice John M. Harlan dissented, arguing that the majority incorrectly interpreted the Rivers and Waters Act.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"United States v. Rio Grande Dam & Irrigation Co.","cite":"174 U.S. 690","y":1899,"id":"scdb/1898-172","sc":1,"op":4,"sum":"Explaining that the Act reaches “any obstruction to the navigable capacity, and anything, wherever done or however done, . . . which tends to destroy the navigable capacity of one of the navigable waters of the United States”.","sumSrc":"opinion","by":{"0":"33-34","2":"18"}},{"t":"case","label":"United States v. Riverside Bayview Homes, Inc.","cite":"474 U.S. 121","y":1985,"id":"1985/84-701","sc":1,"op":13,"sum":"Recognizing that § 1344(g) “at least suggest[s] strongly that the term `waters' as used in the Act does not necessarily exclude `wetlands' ”.","sumSrc":"opinion","by":{"0":"passim","1":"passim","2":"1, 4, 7-8, 10"}},{"t":"case","label":"United States v. Standard Oil Co.","cite":"384 U.S. 224","y":1966,"id":"1965/291","sc":1,"op":1,"sum":"Holding that spilling oil in a navigable water was prohibited by the Refuse Act (§ 13 of the 1899 Act) because “its presence in our rivers and harbors is both a menace to navigation and a pollutant”.","sumSrc":"opinion","by":{"0":"29-30, 33"}},{"t":"case","label":"United States v. Stoeco Homes, Inc.","cite":"498 F.2d 597","y":1974,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/498/597/","op":2,"by":{"0":"32"}},{"t":"case","label":"United States v. U.S. Steel Corp.","cite":"328 F. Supp. 354","y":1970,"court":"N.D. Ind.","url":"https://www.courtlistener.com/c/F.%20Supp./328/354/","by":{"0":"33"}},{"t":"case","label":"Willamette Iron Bridge Co. v. Hatch","cite":"125 U.S. 1","y":1888,"id":"scdb/1887-159","sc":1,"sum":"On a pure bill of review nothing will avail for a reversal of the decree but errors of law apparent on the record.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Zabel v. Tabb","cite":"430 F.2d 199","y":1970,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/430/199/","by":{"0":"33"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"0":"20"}},{"t":"usc","label":"16 U.S.C. § 797","url":"https://www.law.cornell.edu/uscode/text/16/797","subs":["(e)"],"by":{"0":"37"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"33 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/33/401","by":{"0":"31"}},{"t":"usc","label":"33 U.S.C. § 403","url":"https://www.law.cornell.edu/uscode/text/33/403","subs":["(2018)"],"stext":{"head":"§403. Obstruction of navigable waters generally; wharves; piers, etc.; excavations and filling in","paras":[[0,"The creation of any obstruction not affirmatively authorized by Congress, to the navigable capacity of any of the waters of the United States is prohibited; and it shall not be lawful to build or commence the building of any wharf, pier, dolphin, boom, weir, breakwater, bulkhead, jetty, or other structures in any port, roadstead, haven, harbor, canal, navigable river, or other water of the United States, outside established harbor lines, or where no harbor lines have been established, except on plans recommended by the Chief of Engineers and authorized by the Secretary of the Army; and it shall not be lawful to excavate or fill, or in any manner to alter or modify the course, location, condition, or capacity of, any port, roadstead, haven, harbor, canal, lake, harbor of refuge, or inclosure within the limits of any breakwater, or of the channel of any navigable water of the United States, unless the work has been recommended by the Chief of Engineers and authorized by the Secretary of the Army prior to beginning the same."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/403?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§403. Obstruction of navigable waters generally; wharves; piers, etc.; excavations and filling in","tname":"Navigation and Navigable Waters","by":{"0":"30-32","2":"18"}},{"t":"usc","label":"33 U.S.C. § 407","url":"https://www.law.cornell.edu/uscode/text/33/407","subs":["(1970)"],"stext":{"head":"§407. Deposit of refuse in navigable waters generally","paras":[[0,"It shall not be lawful to throw, discharge, or deposit, or cause, suffer, or procure to be thrown, discharged, or deposited either from or out of any ship, barge, or other floating craft of any kind, or from the shore, wharf, manufacturing establishment, or mill of any kind, any refuse matter of any kind or description whatever other than that flowing from streets and sewers and passing therefrom in a liquid state, into any navigable water of the United States, or into any tributary of any navigable water from which the same shall float or be washed into such navigable water; and it shall not be lawful to deposit, or cause, suffer, or procure to be deposited material of any kind in any place on the bank of any navigable water, or on the bank of any tributary of any navigable water, where the same shall be liable to be washed into such navigable water, either by ordinary or high tides, or by storms or floods, or otherwise, whereby navigation shall or may be impeded or obstructed: Provided, That nothing herein contained shall extend to, apply to, or prohibit the operations in connection with the improvement of navigable waters or construction of public works, considered necessary and proper by the United States officers supervising such improvement or public work: And provided further, That the Secretary of the Army, whenever in the judgment of the Chief of Engineers anchorage and navigation will not be injured thereby, may permit the deposit of any material above mentioned in navigable waters, within limits to be defined and under conditions to be prescribed by him, provided application is made to him prior to depositing such material; and whenever any permit is so granted the conditions thereof shall be strictly complied with, and any violation thereof shall be unlawful."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/407?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§407. Deposit of refuse in navigable waters generally","tname":"Navigation and Navigable Waters","by":{"0":"34","1":"4, 47","2":"17"}},{"t":"usc","label":"33 U.S.C. § 466a","url":"https://www.law.cornell.edu/uscode/text/33/466a","subs":["(d)(1)(1952)"],"by":{"0":"34"}},{"t":"usc","label":"33 U.S.C. § 466g","url":"https://www.law.cornell.edu/uscode/text/33/466g","subs":["(a)","(c)(5)"],"by":{"0":"34, 34"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","subs":["(b)","(a)"],"stext":{"head":"§1251. Congressional declaration of goals and policy","paras":[[0,"(a) Restoration and maintenance of chemical, physical and biological integrity of Nation's waters; national goals for achievement of objective"],[0,"The objective of this chapter is to restore and maintain the chemical, physical, and biological integrity of the Nation's waters. In order to achieve this objective it is hereby declared that, consistent with the provisions of this chapter—"],[1,"(1) it is the national goal that the discharge of pollutants into the navigable waters be eliminated by 1985;"],[1,"(2) it is the national goal that wherever attainable, an interim goal of water quality which provides for the protection and propagation of fish, shellfish, and wildlife and provides for recreation in and on the water be achieved by July 1, 1983;"],[1,"(3) it is the national policy that the discharge of toxic pollutants in toxic amounts be prohibited;"],[1,"(4) it is the national policy that Federal financial assistance be provided to construct publicly owned waste treatment works;"],[1,"(5) it is the national policy that areawide waste treatment management planning processes be developed and implemented to assure adequate control of sources of pollutants in each State;"],[1,"(6) it is the national policy that a major research and demonstration effort be made to develop technology necessary to eliminate the discharge of pollutants into the navigable waters, waters of the contiguous zone, and the oceans; and"],[1,"(7) it is the national policy that programs for the control of nonpoint sources of pollution be developed and implemented in an expeditious manner so as to enable the goals of this chapter to be met through the control of both point and nonpoint sources of pollution."],[0,"(b) Congressional recognition, preservation, and protection of primary responsibilities and rights of States"],[0,"It is the policy of the Congress to recognize, preserve, and protect the primary responsibilities and rights of States to prevent, reduce, and eliminate pollution, to plan the development and use (including restoration, preservation, and enhancement) of land and water resources, and to consult with the Administrator in the exercise of his authority under this chapter. It is the policy of Congress that the States manage the construction grant program under this chapter and implement the permit programs under sections 1342 and 1344 of this title. It is further the policy of the Congress to support and aid research relating to the prevention, reduction, and elimination of pollution and to provide Federal technical services and financial aid to State and interstate agencies and municipalities in connection with the prevention, reduction, and elimination of pollution."],[0,"(c) Congressional policy toward Presidential activities with foreign countries"],[0,"It is further the policy of Congress that the President, acting through the Secretary of State and such national and international organizations as he determines appropriate, shall take such action as may be necessary to insure that to the fullest extent possible all foreign countries shall take meaningful action for the prevention, reduction, and elimination of pollution in their waters and in international waters and for the achievement of goals regarding the elimination of discharge of pollutants and the improvement of water quality to at least the same extent as the United States does under its laws."],[0,"(d) Administrator of Environmental Protection Agency to administer chapter"],[0,"Except as otherwise expressly provided in this chapter, the Administrator of the Environmental Protection Agency (hereinafter in this chapter called \"Administrator\") shall administer this chapter."],[0,"(e) Public participation in development, revision, and enforcement of any regulation, etc."],[0,"Public participation in the development, revision, and enforcement of any regulation, standard, effluent limitation, plan, or program established by the Administrator or any State under this chapter shall be provided for, encouraged, and assisted by the Administrator and the States. The Administrator, in cooperation with the States, shall develop and publish regulations specifying minimum guidelines for public participation in such processes."],[0,"(f) Procedures utilized for implementing chapter"],[0,"It is the national policy that to the maximum extent possible the procedures utilized for implementing this chapter shall encourage the drastic minimization of paperwork and interagency decision procedures, and the best use of available manpower and funds, so as to prevent needless duplication and unnecessary delays at all levels of government."],[0,"(g) Authority of States over water"],[0,"It is the policy of Congress that the authority of each State to allocate quantities of water within its jurisdiction shall not be superseded, abrogated or otherwise impaired by this chapter. It is the further policy of Congress that nothing in this chapter shall be construed to supersede or abrogate rights to quantities of water which have been established by any State. Federal agencies shall co-operate with State and local agencies to develop comprehensive solutions to prevent, reduce and eliminate pollution in concert with programs for managing water resources."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1251?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1251. Congressional declaration of goals and policy","tname":"Navigation and Navigable Waters","by":{"0":"4, 45, 15, 46","1":"2, 5, 5, 5","2":"13"}},{"t":"usc","label":"33 U.S.C. § 1311","url":"https://www.law.cornell.edu/uscode/text/33/1311","subs":["(a)"],"stext":{"head":"§1311. Effluent limitations","paras":[[0,"(a) Illegality of pollutant discharges except in compliance with law"],[0,"Except as in compliance with this section and sections 1312, 1316, 1317, 1328, 1342, and 1344 of this title, the discharge of any pollutant by any person shall be unlawful."],[0,"(b) Timetable for achievement of objectives"],[0,"In order to carry out the objective of this chapter there shall be achieved—"],[1,"(1)(A) not later than July 1, 1977, effluent limitations for point sources, other than publicly owned treatment works, (i) which shall require the application of the best practicable control technology currently available as defined by the Administrator pursuant to section 1314(b) of this title, or (ii) in the case of a discharge into a publicly owned treatment works which meets the requirements of subparagraph (B) of this paragraph, which shall require compliance with any applicable pretreatment requirements and any requirements under section 1317 of this title; and"],[1,"(B) for publicly owned treatment works in existence on July 1, 1977, or approved pursuant to section 1283 of this title prior to June 30, 1974 (for which construction must be completed within four years of approval), effluent limitations based upon secondary treatment as defined by the Administrator pursuant to section 1314(d)(1) of this title; or,"],[1,"(C) not later than July 1, 1977, any more stringent limitation, including those necessary to meet water quality standards, treatment standards, or schedules of compliance, established pursuant to any State law or regulations (under authority preserved by section 1370 of this title) or any other Federal law or regulation, or required to implement any applicable water quality standard established pursuant to this chapter."],[1,"(2)(A) for pollutants identified in subparagraphs (C), (D), and (F) of this paragraph, effluent limitations for categories and classes of point sources, other than publicly owned treatment works, which (i) shall require application of the best available technology economically achievable for such category or class, which will result in reasonable further progress toward the national goal of eliminating the discharge of all pollutants, as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(2) of this title, which such effluent limitations shall require the elimination of discharges of all pollutants if the Administrator finds, on the basis of information available to him (including information developed pursuant to section 1325 of this title), that such elimination is technologically and economically achievable for a category or class of point sources as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(2) of this title, or (ii) in the case of the introduction of a pollutant into a publicly owned treatment works which meets the requirements of subparagraph (B) of this paragraph, shall require compliance with any applicable pretreatment requirements and any other requirement under section 1317 of this title;"],[1,"(B) Repealed. Pub. L. 97–117, §21(b), Dec. 29, 1981, 95 Stat. 1632."],[1,"(C) with respect to all toxic pollutants referred to in table 1 of Committee Print Numbered 95–30 of the Committee on Public Works and Transportation of the House of Representatives compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989;"],[1,"(D) for all toxic pollutants listed under paragraph (1) of subsection (a) of section 1317 of this title which are not referred to in subparagraph (C) of this paragraph compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable, but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989;"],[1,"(E) as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989, compliance with effluent limitations for categories and classes of point sources, other than publicly owned treatment works, which in the case of pollutants identified pursuant to section 1314(a)(4) of this title shall require application of the best conventional pollutant control technology as determined in accordance with regulations issued by the Administrator pursuant to section 1314(b)(4) of this title; and"],[1,"(F) for all pollutants (other than those subject to subparagraphs (C), (D), or (E) of this paragraph) compliance with effluent limitations in accordance with subparagraph (A) of this paragraph as expeditiously as practicable but in no case later than 3 years after the date such limitations are established, and in no case later than March 31, 1989."],[1,"(3)(A) for effluent limitations under paragraph (1)(A)(i) of this subsection promulgated after January 1, 1982, and requiring a level of control substantially greater or based on fundamentally different control technology than under permits for an industrial category issued before such date, compliance as expeditiously as practicable but in no case later than three years after the date such limitations are promulgated under section 1314(b) of this title, and in no case later than March 31, 1989; and"],[1,"(B) for any effluent limitation in accordance with paragraph (1)(A)(i), (2)(A)(i), or (2)(E) of this subsection established only on the basis of section 1342(a)(1) of this title in a permit issued after February 4, 1987, compliance as expeditiously as practicable but in no case later than three years after the date such limitations are established, and in no case later than March 31, 1989."],[0,"(c) Modification of timetable"],[0,"The Administrator may modify the requirements of subsection (b)(2)(A) of this section with respect to any point source for which a permit application is filed after July 1, 1977, upon a showing by the owner or operator of such point source satisfactory to the Administrator that such modified requirements (1) will represent the maximum use of technology within the economic capability of the owner or operator; and (2) will result in reasonable further progress toward the elimination of the discharge of pollutants."],[0,"(d) Review and revision of effluent limitations"],[0,"Any effluent limitation required by paragraph (2) of subsection (b) of this section shall be reviewed at least every five years and, if appropriate, revised pursuant to the procedure established under such paragraph."],[0,"(e) All point discharge source application of effluent limitations"],[0,"Effluent limitations established pursuant to this section or section 1312 of this title shall be applied to all point sources of discharge of pollutants in accordance with the provisions of this chapter."],[0,"(f) Illegality of discharge of radiological, chemical, or biological warfare agents, high-level radioactive waste, or medical waste"],[0,"Notwithstanding any other provisions of this chapter it shall be unlawful to discharge any radiological, chemical, or biological warfare agent, any high-level radioactive waste, or any medical waste, into the navigable waters."],[0,"(g) Modifications for certain nonconventional pollutants"],[0,"(1) General authority"],[1,"The Administrator, with the concurrence of the State, may modify the requirements of subsection (b)(2)(A) of this section with respect to the discharge from any point source of ammonia, chlorine, color, iron, and total phenols (4AAP) (when determined by the Administrator to be a pollutant covered by subsection (b)(2)(F)) and any other pollutant which the Administrator lists under paragraph (4) of this subsection."],[0,"(2) Requirements for granting modifications"],[1,"A modification under this subsection shall be granted only upon a showing by the owner or operator of a point source satisfactory to the Administrator that—"],[2,"(A) such modified requirements will result at a minimum in compliance with the requirements of subsection (b)(1)(A) or (C) of this section, whichever is applicable;"],[2,"(B) such modified requirements will not result in any additional requirements on any other point or nonpoint source; and"],[2,"(C) such modification will not interfere with the attainment or maintenance of that water quality which shall assure protection of public water supplies, and the protection and propagation of a balanced population of shellfish, fish, and wildlife, and allow recreational activities, in and on the water and such modification will not result in the discharge of pollutants in quantities which may reasonably be anticipated to pose an unacceptable risk to human health or the environment because of bioaccumulation, persistency in the environment, acute toxicity, chronic toxicity (including carcinogenicity, mutagenicity or teratogenicity), or synergistic propensities."],[0,"(3) Limitation on authority to apply for subsection (c) modification"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1311?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1311. Effluent limitations","tname":"Navigation and Navigable Waters","by":{"0":"9, 25","1":"2"}},{"t":"usc","label":"33 U.S.C. § 1318","url":"https://www.law.cornell.edu/uscode/text/33/1318","by":{"0":"18"}},{"t":"usc","label":"33 U.S.C. § 1319","url":"https://www.law.cornell.edu/uscode/text/33/1319","subs":["(a)(3)"],"stext":{"head":"§1319. Enforcement","paras":[[0,"(a) State enforcement; compliance orders"],[0,"(1) Whenever, on the basis of any information available to him, the Administrator finds that any person is in violation of any condition or limitation which implements section 1311, 1312, 1316, 1317, 1318, 1328, or 1345 of this title in a permit issued by a State under an approved permit program under section 1342 or 1344 of this title he shall proceed under his authority in paragraph (3) of this subsection or he shall notify the person in alleged violation and such State of such finding. If beyond the thirtieth day after the Administrator's notification the State has not commenced appropriate enforcement action, the Administrator shall issue an order requiring such person to comply with such condition or limitation or shall bring a civil action in accordance with subsection (b) of this section."],[0,"(2) Whenever, on the basis of information available to him, the Administrator finds that violations of permit conditions or limitations as set forth in paragraph (1) of this subsection are so widespread that such violations appear to result from a failure of the State to enforce such permit conditions or limitations effectively, he shall so notify the State. If the Administrator finds such failure extends beyond the thirtieth day after such notice, he shall give public notice of such finding. During the period beginning with such public notice and ending when such State satisfies the Administrator that it will enforce such conditions and limitations (hereafter referred to in this section as the period of \"federally assumed enforcement\"), except where an extension has been granted under paragraph (5)(B) of this subsection, the Administrator shall enforce any permit condition or limitation with respect to any person—"],[1,"(A) by issuing an order to comply with such condition or limitation, or"],[1,"(B) by bringing a civil action under subsection (b) of this section."],[0,"(3) Whenever on the basis of any information available to him the Administrator finds that any person is in violation of section 1311, 1312, 1316, 1317, 1318, 1322(p), 1328, or 1345 of this title, or is in violation of any permit condition or limitation implementing any of such sections in a permit issued under section 1342 of this title by him or by a State or in a permit issued under section 1344 of this title by a State, he shall issue an order requiring such person to comply with such section or requirement, or he shall bring a civil action in accordance with subsection (b) of this section."],[0,"(4) A copy of any order issued under this subsection shall be sent immediately by the Administrator to the State in which the violation occurs and other affected States. In any case in which an order under this subsection (or notice to a violator under paragraph (1) of this subsection) is issued to a corporation, a copy of such order (or notice) shall be served on any appropriate corporate officers. An order issued under this subsection relating to a violation of section 1318 of this title shall not take effect until the person to whom it is issued has had an opportunity to confer with the Administrator concerning the alleged violation."],[0,"(5)(A) Any order issued under this subsection shall be by personal service, shall state with reasonable specificity the nature of the violation, and shall specify a time for compliance not to exceed thirty days in the case of a violation of an interim compliance schedule or operation and maintenance requirement and not to exceed a time the Administrator determines to be reasonable in the case of a violation of a final deadline, taking into account the seriousness of the violation and any good faith efforts to comply with applicable requirements."],[0,"(B) The Administrator may, if he determines (i) that any person who is a violator of, or any person who is otherwise not in compliance with, the time requirements under this chapter or in any permit issued under this chapter, has acted in good faith, and has made a commitment (in the form of contracts or other securities) of necessary resources to achieve compliance by the earliest possible date after July 1, 1977, but not later than April 1, 1979; (ii) that any extension under this provision will not result in the imposition of any additional controls on any other point or nonpoint source; (iii) that an application for a permit under section 1342 of this title was filed for such person prior to December 31, 1974; and (iv) that the facilities necessary for compliance with such requirements are under construction, grant an extension of the date referred to in section 1311(b)(1)(A) of this title to a date which will achieve compliance at the earliest time possible but not later than April 1, 1979."],[0,"(6) Whenever, on the basis of information available to him, the Administrator finds (A) that any person is in violation of section 1311(b)(1)(A) or (C) of this title, (B) that such person cannot meet the requirements for a time extension under section 1311(i)(2) of this title, and (C) that the most expeditious and appropriate means of compliance with this chapter by such person is to discharge into a publicly owned treatment works, then, upon request of such person, the Administrator may issue an order requiring such person to comply with this chapter at the earliest date practicable, but not later than July 1, 1983, by discharging into a publicly owned treatment works if such works concur with such order. Such order shall include a schedule of compliance."],[0,"(b) Civil actions"],[0,"The Administrator is authorized to commence a civil action for appropriate relief, including a permanent or temporary injunction, for any violation for which he is authorized to issue a compliance order under subsection (a) of this section. Any action under this subsection may be brought in the district court of the United States for the district in which the defendant is located or resides or is doing business, and such court shall have jurisdiction to restrain such violation and to require compliance. Notice of the commencement of such action shall be given immediately to the appropriate State."],[0,"(c) Criminal penalties"],[0,"(1) Negligent violations"],[1,"Any person who—"],[2,"(A) negligently violates section 1311, 1312, 1316, 1317, 1318, 1321(b)(3), 1322(p), 1328, or 1345 of this title, or any permit condition or limitation implementing any of such sections in a permit issued under section 1342 of this title by the Administrator or by a State, or any requirement imposed in a pretreatment program approved under section 1342(a)(3) or 1342(b)(8) of this title or in a permit issued under section 1344 of this title by the Secretary of the Army or by a State; or"],[2,"(B) negligently introduces into a sewer system or into a publicly owned treatment works any pollutant or hazardous substance which such person knew or reasonably should have known could cause personal injury or property damage or, other than in compliance with all applicable Federal, State, or local requirements or permits, which causes such treatment works to violate any effluent limitation or condition in any permit issued to the treatment works under section 1342 of this title by the Administrator or a State;"],[1,"shall be punished by a fine of not less than $2,500 nor more than $25,000 per day of violation, or by imprisonment for not more than 1 year, or by both. If a conviction of a person is for a violation committed after a first conviction of such person under this paragraph, punishment shall be by a fine of not more than $50,000 per day of violation, or by imprisonment of not more than 2 years, or by both."],[0,"(2) Knowing violations"],[1,"Any person who—"],[2,"(A) knowingly violates section 1311, 1312, 1316, 1317, 1318, 1321(b)(3), 1322(p), 1328, or 1345 of this title, or any permit condition or limitation implementing any of such sections in a permit issued under section 1342 of this title by the Administrator or by a State, or any requirement imposed in a pretreatment program approved under section 1342(a)(3) or 1342(b)(8) of this title or in a permit issued under section 1344 of this title by the Secretary of the Army or by a State; or"],[2,"(B) knowingly introduces into a sewer system or into a publicly owned treatment works any pollutant or hazardous substance which such person knew or reasonably should have known could cause personal injury or property damage or, other than in compliance with all applicable Federal, State, or local requirements or permits, which causes such treatment works to violate any effluent limitation or condition in a permit issued to the treatment works under section 1342 of this title by the Administrator or a State;"],[1,"shall be punished by a fine of not less than $5,000 nor more than $50,000 per day of violation, or by imprisonment for not more than 3 years, or by both. If a conviction of a person is for a violation committed after a first conviction of such person under this paragraph, punishment shall be by a fine of not more than $100,000 per day of violation, or by imprisonment of not more than 6 years, or by both."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1319?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1319. Enforcement","tname":"Navigation and Navigable Waters","by":{"0":"19","1":"10"}},{"t":"usc","label":"33 U.S.C. § 1342","url":"https://www.law.cornell.edu/uscode/text/33/1342","subs":["(a)","(b)"],"stext":{"head":"§1342. National pollutant discharge elimination system","paras":[[0,"(a) Permits for discharge of pollutants"],[0,"(1) Except as provided in sections 1328 and 1344 of this title, the Administrator may, after opportunity for public hearing issue a permit for the discharge of any pollutant, or combination of pollutants, notwithstanding section 1311(a) of this title, upon condition that such discharge will meet either (A) all applicable requirements under sections 1311, 1312, 1316, 1317, 1318, and 1343 of this title, or (B) prior to the taking of necessary implementing actions relating to all such requirements, such conditions as the Administrator determines are necessary to carry out the provisions of this chapter."],[0,"(2) The Administrator shall prescribe conditions for such permits to assure compliance with the requirements of paragraph (1) of this subsection, including conditions on data and information collection, reporting, and such other requirements as he deems appropriate."],[0,"(3) The permit program of the Administrator under paragraph (1) of this subsection, and permits issued thereunder, shall be subject to the same terms, conditions, and requirements as apply to a State permit program and permits issued thereunder under subsection (b) of this section."],[0,"(4) All permits for discharges into the navigable waters issued pursuant to section 407 of this title shall be deemed to be permits issued under this subchapter, and permits issued under this subchapter shall be deemed to be permits issued under section 407 of this title, and shall continue in force and effect for their term unless revoked, modified, or suspended in accordance with the provisions of this chapter."],[0,"(5) No permit for a discharge into the navigable waters shall be issued under section 407 of this title after October 18, 1972. Each application for a permit under section 407 of this title, pending on October 18, 1972, shall be deemed to be an application for a permit under this section. The Administrator shall authorize a State, which he determines has the capability of administering a permit program which will carry out the objectives of this chapter to issue permits for discharges into the navigable waters within the jurisdiction of such State. The Administrator may exercise the authority granted him by the preceding sentence only during the period which begins on October 18, 1972, and ends either on the ninetieth day after the date of the first promulgation of guidelines required by section 1314(i)(2) of this title, or the date of approval by the Administrator of a permit program for such State under subsection (b) of this section, whichever date first occurs, and no such authorization to a State shall extend beyond the last day of such period. Each such permit shall be subject to such conditions as the Administrator determines are necessary to carry out the provisions of this chapter. No such permit shall issue if the Administrator objects to such issuance."],[0,"(b) State permit programs"],[0,"At any time after the promulgation of the guidelines required by subsection (i)(2) of section 1314 of this title, the Governor of each State desiring to administer its own permit program for discharges into navigable waters within its jurisdiction may submit to the Administrator a full and complete description of the program it proposes to establish and administer under State law or under an interstate compact. In addition, such State shall submit a statement from the attorney general (or the attorney for those State water pollution control agencies which have independent legal counsel), or from the chief legal officer in the case of an interstate agency, that the laws of such State, or the interstate compact, as the case may be, provide adequate authority to carry out the described program. The Administrator shall approve each submitted program unless he determines that adequate authority does not exist:"],[0,"(1) To issue permits which—"],[1,"(A) apply, and insure compliance with, any applicable requirements of sections 1311, 1312, 1316, 1317, and 1343 of this title;"],[1,"(B) are for fixed terms not exceeding five years; and"],[1,"(C) can be terminated or modified for cause including, but not limited to, the following:"],[2,"(i) violation of any condition of the permit;"],[2,"(ii) obtaining a permit by misrepresentation, or failure to disclose fully all relevant facts;"],[2,"(iii) change in any condition that requires either a temporary or permanent reduction or elimination of the permitted discharge;"],[1,"(D) control the disposal of pollutants into wells;"],[0,"(2)(A) To issue permits which apply, and insure compliance with, all applicable requirements of section 1318 of this title; or"],[0,"(B) To inspect, monitor, enter, and require reports to at least the same extent as required in section 1318 of this title;"],[0,"(3) To insure that the public, and any other State the waters of which may be affected, receive notice of each application for a permit and to provide an opportunity for public hearing before a ruling on each such application;"],[0,"(4) To insure that the Administrator receives notice of each application (including a copy thereof) for a permit;"],[0,"(5) To insure that any State (other than the permitting State), whose waters may be affected by the issuance of a permit may submit written recommendations to the permitting State (and the Administrator) with respect to any permit application and, if any part of such written recommendations are not accepted by the permitting State, that the permitting State will notify such affected State (and the Administrator) in writing of its failure to so accept such recommendations together with its reasons for so doing;"],[0,"(6) To insure that no permit will be issued if, in the judgment of the Secretary of the Army acting through the Chief of Engineers, after consultation with the Secretary of the department in which the Coast Guard is operating, anchorage and navigation of any of the navigable waters would be substantially impaired thereby;"],[0,"(7) To abate violations of the permit or the permit program, including civil and criminal penalties and other ways and means of enforcement;"],[0,"(8) To insure that any permit for a discharge from a publicly owned treatment works includes conditions to require the identification in terms of character and volume of pollutants of any significant source introducing pollutants subject to pretreatment standards under section 1317(b) of this title into such works and a program to assure compliance with such pretreatment standards by each such source, in addition to adequate notice to the permitting agency of (A) new introductions into such works of pollutants from any source which would be a new source as defined in section 1316 of this title if such source were discharging pollutants, (B) new introductions of pollutants into such works from a source which would be subject to section 1311 of this title if it were discharging such pollutants, or (C) a substantial change in volume or character of pollutants being introduced into such works by a source introducing pollutants into such works at the time of issuance of the permit. Such notice shall include information on the quality and quantity of effluent to be introduced into such treatment works and any anticipated impact of such change in the quantity or quality of effluent to be discharged from such publicly owned treatment works; and"],[0,"(9) To insure that any industrial user of any publicly owned treatment works will comply with sections 1284(b), 1317, and 1318 of this title."],[0,"(c) Suspension of Federal program upon submission of State program; withdrawal of approval of State program; return of State program to Administrator"],[0,"(1) Not later than ninety days after the date on which a State has submitted a program (or revision thereof) pursuant to subsection (b) of this section, the Administrator shall suspend the issuance of permits under subsection (a) of this section as to those discharges subject to such program unless he determines that the State permit program does not meet the requirements of subsection (b) of this section or does not conform to the guidelines issued under section 1314(i)(2) of this title. If the Administrator so determines, he shall notify the State of any revisions or modifications necessary to conform to such requirements or guidelines."],[0,"(2) Any State permit program under this section shall at all times be in accordance with this section and guidelines promulgated pursuant to section 1314(i)(2) of this title."],[0,"(3) Whenever the Administrator determines after public hearing that a State is not administering a program approved under this section in accordance with requirements of this section, he shall so notify the State and, if appropriate corrective action is not taken within a reasonable time, not to exceed ninety days, the Administrator shall withdraw approval of such program. The Administrator shall not withdraw approval of any such program unless he shall first have notified the State, and made public, in writing, the reasons for such withdrawal."],[0,"(4) Limitations on partial permit program returns and withdrawals.—A State may return to the Administrator administration, and the Administrator may withdraw under paragraph (3) of this subsection approval, of—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1342?type=usc&year=mostrecent&link-type=html"},"head":"§1342. National pollutant discharge elimination system","tname":"Navigation and Navigable Waters","by":{"0":"10, 10","1":"2, 5, 5"}},{"t":"usc","label":"33 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/33/1344","subs":["(a)","(e)","(g)","(g)(1)","(h)","(e)(1)","(f)(1)(C)","(f)(2)"],"stext":{"head":"§1344. Permits for dredged or fill material","paras":[[0,"(a) Discharge into navigable waters at specified disposal sites"],[0,"The Secretary may issue permits, after notice and opportunity for public hearings for the discharge of dredged or fill material into the navigable waters at specified disposal sites. Not later than the fifteenth day after the date an applicant submits all the information required to complete an application for a permit under this subsection, the Secretary shall publish the notice required by this subsection."],[0,"(b) Specification for disposal sites"],[0,"Subject to subsection (c) of this section, each such disposal site shall be specified for each such permit by the Secretary (1) through the application of guidelines developed by the Administrator, in conjunction with the Secretary, which guidelines shall be based upon criteria comparable to the criteria applicable to the territorial seas, the contiguous zone, and the ocean under section 1343(c) of this title, and (2) in any case where such guidelines under clause (1) alone would prohibit the specification of a site, through the application additionally of the economic impact of the site on navigation and anchorage."],[0,"(c) Denial or restriction of use of defined areas as disposal sites"],[0,"The Administrator is authorized to prohibit the specification (including the withdrawal of specification) of any defined area as a disposal site, and he is authorized to deny or restrict the use of any defined area for specification (including the withdrawal of specification) as a disposal site, whenever he determines, after notice and opportunity for public hearings, that the discharge of such materials into such area will have an unacceptable adverse effect on municipal water supplies, shellfish beds and fishery areas (including spawning and breeding areas), wildlife, or recreational areas. Before making such determination, the Administrator shall consult with the Secretary. The Administrator shall set forth in writing and make public his findings and his reasons for making any determination under this subsection."],[0,"(d) \"Secretary\" defined"],[0,"The term \"Secretary\" as used in this section means the Secretary of the Army, acting through the Chief of Engineers."],[0,"(e) General permits on State, regional, or nationwide basis"],[0,"(1) In carrying out his functions relating to the discharge of dredged or fill material under this section, the Secretary may, after notice and opportunity for public hearing, issue general permits on a State, regional, or nationwide basis for any category of activities involving discharges of dredged or fill material if the Secretary determines that the activities in such category are similar in nature, will cause only minimal adverse environmental effects when performed separately, and will have only minimal cumulative adverse effect on the environment. Any general permit issued under this subsection shall (A) be based on the guidelines described in subsection (b)(1) of this section, and (B) set forth the requirements and standards which shall apply to any activity authorized by such general permit."],[0,"(2) No general permit issued under this subsection shall be for a period of more than five years after the date of its issuance and such general permit may be revoked or modified by the Secretary if, after opportunity for public hearing, the Secretary determines that the activities authorized by such general permit have an adverse impact on the environment or such activities are more appropriately authorized by individual permits."],[0,"(f) Non-prohibited discharge of dredged or fill material"],[0,"(1) Except as provided in paragraph (2) of this subsection, the discharge of dredged or fill material—"],[1,"(A) from normal farming, silviculture, and ranching activities such as plowing, seeding, cultivating, minor drainage, harvesting for the production of food, fiber, and forest products, or upland soil and water conservation practices;"],[1,"(B) for the purpose of maintenance, including emergency reconstruction of recently damaged parts, of currently serviceable structures such as dikes, dams, levees, groins, riprap, breakwaters, causeways, and bridge abutments or approaches, and transportation structures;"],[1,"(C) for the purpose of construction or maintenance of farm or stock ponds or irrigation ditches, or the maintenance of drainage ditches;"],[1,"(D) for the purpose of construction of temporary sedimentation basins on a construction site which does not include placement of fill material into the navigable waters;"],[1,"(E) for the purpose of construction or maintenance of farm roads or forest roads, or temporary roads for moving mining equipment, where such roads are constructed and maintained, in accordance with best management practices, to assure that flow and circulation patterns and chemical and biological characteristics of the navigable waters are not impaired, that the reach of the navigable waters is not reduced, and that any adverse effect on the aquatic environment will be otherwise minimized;"],[1,"(F) resulting from any activity with respect to which a State has an approved program under section 1288(b)(4) of this title which meets the requirements of subparagraphs (B) and (C) of such section,"],[0,"is not prohibited by or otherwise subject to regulation under this section or section 1311(a) or 1342 of this title (except for effluent standards or prohibitions under section 1317 of this title)."],[0,"(2) Any discharge of dredged or fill material into the navigable waters incidental to any activity having as its purpose bringing an area of the navigable waters into a use to which it was not previously subject, where the flow or circulation of navigable waters may be impaired or the reach of such waters be reduced, shall be required to have a permit under this section."],[0,"(g) State administration"],[0,"(1) The Governor of any State desiring to administer its own individual and general permit program for the discharge of dredged or fill material into the navigable waters (other than those waters which are presently used, or are susceptible to use in their natural condition or by reasonable improvement as a means to transport interstate or foreign commerce shoreward to their ordinary high water mark, including all waters which are subject to the ebb and flow of the tide shoreward to their mean high water mark, or mean higher high water mark on the west coast, including wetlands adjacent thereto) within its jurisdiction may submit to the Administrator a full and complete description of the program it proposes to establish and administer under State law or under an interstate compact. In addition, such State shall submit a statement from the attorney general (or the attorney for those State agencies which have independent legal counsel), or from the chief legal officer in the case of an interstate agency, that the laws of such State, or the interstate compact, as the case may be, provide adequate authority to carry out the described program."],[0,"(2) Not later than the tenth day after the date of the receipt of the program and statement submitted by any State under paragraph (1) of this subsection, the Administrator shall provide copies of such program and statement to the Secretary and the Secretary of the Interior, acting through the Director of the United States Fish and Wildlife Service."],[0,"(3) Not later than the ninetieth day after the date of the receipt by the Administrator of the program and statement submitted by any State, under paragraph (1) of this subsection, the Secretary and the Secretary of the Interior, acting through the Director of the United States Fish and Wildlife Service, shall submit any comments with respect to such program and statement to the Administrator in writing."],[0,"(h) Determination of State's authority to issue permits under State program; approval; notification; transfers to State program"],[0,"(1) Not later than the one-hundred-twentieth day after the date of the receipt by the Administrator of a program and statement submitted by any State under paragraph (1) of this subsection, the Administrator shall determine, taking into account any comments submitted by the Secretary and the Secretary of the Interior, acting through the Director of the United States Fish and Wildlife Service, pursuant to subsection (g) of this section, whether such State has the following authority with respect to the issuance of permits pursuant to such program:"],[1,"(A) To issue permits which—"],[2,"(i) apply, and assure compliance with, any applicable requirements of this section, including, but not limited to, the guidelines established under subsection (b)(1) of this section, and sections 1317 and 1343 of this title;"],[2,"(ii) are for fixed terms not exceeding five years; and"],[2,"(iii) can be terminated or modified for cause including, but not limited to, the following:"],[3,"(I) violation of any condition of the permit;"],[3,"(II) obtaining a permit by misrepresentation, or failure to disclose fully all relevant facts;"],[3,"(III) change in any condition that requires either a temporary or permanent reduction or elimination of the permitted discharge."],[1,"(B) To issue permits which apply, and assure compliance with, all applicable requirements of section 1318 of this title, or to inspect, monitor, enter, and require reports to at least the same extent as required in section 1318 of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1344?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§1344. Permits for dredged or fill material","tname":"Navigation and Navigable Waters","by":{"0":"10, 51, 10, 27, 10","1":"38, 38, 38, 38, 38, 38, 38","2":"14, 11, 6"}},{"t":"usc","label":"33 U.S.C. § 1362","url":"https://www.law.cornell.edu/uscode/text/33/1362","subs":["(7)","(8)","(12)","(14)","(6)","(12)(A)"],"stext":{"head":"§1362. Definitions","paras":[[0,"Except as otherwise specifically provided, when used in this chapter:"],[0,"(1) The term \"State water pollution control agency\" means the State agency designated by the Governor having responsibility for enforcing State laws relating to the abatement of pollution."],[0,"(2) The term \"interstate agency\" means an agency of two or more States established by or pursuant to an agreement or compact approved by the Congress, or any other agency of two or more States, having substantial powers or duties pertaining to the control of pollution as determined and approved by the Administrator."],[0,"(3) The term \"State\" means a State, the District of Columbia, the Commonwealth of Puerto Rico, the Virgin Islands, Guam, American Samoa, the Commonwealth of the Northern Mariana Islands, and the Trust Territory of the Pacific Islands."],[0,"(4) The term \"municipality\" means a city, town, borough, county, parish, district, association, or other public body created by or pursuant to State law and having jurisdiction over disposal of sewage, industrial wastes, or other wastes, or an Indian tribe or an authorized Indian tribal organization, or a designated and approved management agency under section 1288 of this title."],[0,"(5) The term \"person\" means an individual, corporation, partnership, association, State, municipality, commission, or political subdivision of a State, or any interstate body."],[0,"(6) The term \"pollutant\" means dredged spoil, solid waste, incinerator residue, sewage, garbage, sewage sludge, munitions, chemical wastes, biological materials, radioactive materials, heat, wrecked or discarded equipment, rock, sand, cellar dirt and industrial, municipal, and agricultural waste discharged into water. This term does not mean (A) \"sewage from vessels or a discharge incidental to the normal operation of a vessel of the Armed Forces\" within the meaning of section 1322 of this title; or (B) water, gas, or other material which is injected into a well to facilitate production of oil or gas, or water derived in association with oil or gas production and disposed of in a well, if the well used either to facilitate production or for disposal purposes is approved by authority of the State in which the well is located, and if such State determines that such injection or disposal will not result in the degradation of ground or surface water resources."],[0,"(7) The term \"navigable waters\" means the waters of the United States, including the territorial seas."],[0,"(8) The term \"territorial seas\" means the belt of the seas measured from the line of ordinary low water along that portion of the coast which is in direct contact with the open sea and the line marking the seaward limit of inland waters, and extending seaward a distance of three miles."],[0,"(9) The term \"contiguous zone\" means the entire zone established or to be established by the United States under article 24 of the Convention of the Territorial Sea and the Contiguous Zone."],[0,"(10) The term \"ocean\" means any portion of the high seas beyond the contiguous zone."],[0,"(11) The term \"effluent limitation\" means any restriction established by a State or the Administrator on quantities, rates, and concentrations of chemical, physical, biological, and other constituents which are discharged from point sources into navigable waters, the waters of the contiguous zone, or the ocean, including schedules of compliance."],[0,"(12) The term \"discharge of a pollutant\" and the term \"discharge of pollutants\" each means (A) any addition of any pollutant to navigable waters from any point source, (B) any addition of any pollutant to the waters of the contiguous zone or the ocean from any point source other than a vessel or other floating craft."],[0,"(13) The term \"toxic pollutant\" means those pollutants, or combinations of pollutants, including disease-causing agents, which after discharge and upon exposure, ingestion, inhalation or assimilation into any organism, either directly from the environment or indirectly by ingestion through food chains, will, on the basis of information available to the Administrator, cause death, disease, behavioral abnormalities, cancer, genetic mutations, physiological malfunctions (including malfunctions in reproduction) or physical deformations, in such organisms or their offspring."],[0,"(14) The term \"point source\" means any discernible, confined and discrete conveyance, including but not limited to any pipe, ditch, channel, tunnel, conduit, well, discrete fissure, container, rolling stock, concentrated animal feeding operation, or vessel or other floating craft, from which pollutants are or may be discharged. This term does not include agricultural stormwater discharges and return flows from irrigated agriculture."],[0,"(15) The term \"biological monitoring\" shall mean the determination of the effects on aquatic life, including accumulation of pollutants in tissue, in receiving waters due to the discharge of pollutants (A) by techniques and procedures, including sampling of organisms representative of appropriate levels of the food chain appropriate to the volume and the physical, chemical, and biological characteristics of the effluent, and (B) at appropriate frequencies and locations."],[0,"(16) The term \"discharge\" when used without qualification includes a discharge of a pollutant, and a discharge of pollutants."],[0,"(17) The term \"schedule of compliance\" means a schedule of remedial measures including an enforceable sequence of actions or operations leading to compliance with an effluent limitation, other limitation, prohibition, or standard."],[0,"(18) The term \"industrial user\" means those industries identified in the Standard Industrial Classification Manual, Bureau of the Budget, 1967, as amended and supplemented, under the category of \"Division D—Manufacturing\" and such other classes of significant waste producers as, by regulation, the Administrator deems appropriate."],[0,"(19) The term \"pollution\" means the man-made or man-induced alteration of the chemical, physical, biological, and radiological integrity of water."],[0,"(20) The term \"medical waste\" means isolation wastes; infectious agents; human blood and blood products; pathological wastes; sharps; body parts; contaminated bedding; surgical wastes and potentially contaminated laboratory wastes; dialysis wastes; and such additional medical items as the Administrator shall prescribe by regulation."],[0,"(21) Coastal recreation waters.—"],[1,"(A) In general.—The term \"coastal recreation waters\" means—"],[2,"(i) the Great Lakes; and"],[2,"(ii) marine coastal waters (including coastal estuaries) that are designated under section 1313(c) of this title by a State for use for swimming, bathing, surfing, or similar water contact activities."],[1,"(B) Exclusions.—The term \"coastal recreation waters\" does not include—"],[2,"(i) inland waters; or"],[2,"(ii) waters upstream of the mouth of a river or stream having an unimpaired natural connection with the open sea."],[0,"(22) Floatable material.—"],[1,"(A) In general.—The term \"floatable material\" means any foreign matter that may float or remain suspended in the water column."],[1,"(B) Inclusions.—The term \"floatable material\" includes—"],[2,"(i) plastic;"],[2,"(ii) aluminum cans;"],[2,"(iii) wood products;"],[2,"(iv) bottles; and"],[2,"(v) paper products."],[0,"(23) Pathogen indicator.—The term \"pathogen indicator\" means a substance that indicates the potential for human infectious disease."],[0,"(24) Oil and gas exploration and production.—The term \"oil and gas exploration, production, processing, or treatment operations or transmission facilities\" means all field activities or operations associated with exploration, production, processing, or treatment operations, or transmission facilities, including activities necessary to prepare a site for drilling and for the movement and placement of drilling equipment, whether or not such field activities or operations may be considered to be construction activities."],[0,"(25) Recreational vessel.—"],[1,"(A) In general.—The term \"recreational vessel\" means any vessel that is—"],[2,"(i) manufactured or used primarily for pleasure; or"],[2,"(ii) leased, rented, or chartered to a person for the pleasure of that person."],[1,"(B) Exclusion.—The term \"recreational vessel\" does not include a vessel that is subject to Coast Guard inspection and that—"],[2,"(i) is engaged in commercial use; or"],[2,"(ii) carries paying passengers."],[0,"(26) Treatment works.—The term \"treatment works\" has the meaning given the term in section 1292 of this title."],[0,"(27) Green infrastructure.—The term \"green infrastructure\" means the range of measures that use plant or soil systems, permeable pavement or other permeable surfaces or substrates, stormwater harvest and reuse, or landscaping to store, infiltrate, or evapotranspirate stormwater and reduce flows to sewer systems or to surface waters."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1362?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1362. Definitions","tname":"Navigation and Navigable Waters","by":{"0":"1, 4-5, 9, 25, 44, 9, 9, 25, 51","1":"5, 7, 21, 5, 7, 21, 5, 7, 21","2":"1"}},{"t":"usc","label":"43 U.S.C. § 982","url":"https://www.law.cornell.edu/uscode/text/43/982","by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 95-217","url":"https://www.govinfo.gov/link/statute/91/1566","by":{"0":"27","1":"6"}},{"t":"law","label":"Federal Water Pollution Control Act, Pub. L. No. 80-845","by":{"0":"34"}},{"t":"law","label":"Pub. L. No. 87-88","url":"https://www.govinfo.gov/link/statute/75/204","by":{"0":"34"}},{"t":"law","label":"National Water Commission Act, Pub. L. No. 90-515","url":"https://www.govinfo.gov/link/statute/82/868","by":{"0":"41"}},{"t":"law","label":"Outdoor Recreation Resources Review Act, Pub. L. No. 85-470","url":"https://www.govinfo.gov/link/statute/72/238","by":{"0":"27","2":"4"}},{"t":"law","label":"Pub. L. No. 92-500","url":"https://www.govinfo.gov/link/statute/86/816","by":{"0":"27","1":"5"}},{"t":"law","label":"Pub. L. No. 89-234","url":"https://www.govinfo.gov/link/statute/79/903","by":{"0":"34"}},{"t":"law","label":"Wetland Loan Act, Pub. L. No. 87-383","url":"https://www.govinfo.gov/link/statute/75/813","by":{"0":"27"}},{"t":"reg","label":"33 C.F.R. § 209.260","url":"https://www.ecfr.gov/current/title-33/section-209.260","subs":["(a)","(e)(1)","(f)"],"by":{"0":"36, 40, 40-41","2":"17"}},{"t":"reg","label":"33 C.F.R. § 323.2","url":"https://www.ecfr.gov/current/title-33/section-323.2","subs":["(a)(2)","(c)","(d)"],"by":{"0":"12, 12","1":"9"}},{"t":"reg","label":"33 C.F.R. § 328.3","url":"https://www.ecfr.gov/current/title-33/section-328.3","subs":["(a)","(b)","(c)"],"by":{"0":"1-3, 12, 1, 3, 12, 25, 1, 3-4"}},{"t":"reg","label":"33 C.F.R. § 330.2","url":"https://www.ecfr.gov/current/title-33/section-330.2","subs":["(d)"],"by":{"0":"51"}},{"t":"reg","label":"40 C.F.R. § 122.2","url":"https://www.ecfr.gov/current/title-40/section-122.2","by":{"0":"12"}},{"t":"reg","label":"40 C.F.R. § 125.1","url":"https://www.ecfr.gov/current/title-40/section-125.1","subs":["(p)(2)","(p)(4)","(p)(6)"],"by":{"0":"11, 11, 11"}},{"t":"reg","label":"40 C.F.R. § 230.3","url":"https://www.ecfr.gov/current/title-40/section-230.3","subs":["(s)","(t)"],"by":{"0":"12, 12","2":"10"}},{"t":"reg","label":"Other Authorities, 38 Fed. Reg. 13,528","url":"https://www.govinfo.gov/link/fr/38/13528","by":{"0":"11","1":"6"}},{"t":"reg","label":"39 Fed. Reg. 12,115","url":"https://www.govinfo.gov/link/fr/39/12115","by":{"0":"11","1":"5, 20"}},{"t":"reg","label":"42 Fed. Reg. 37,122","url":"https://www.govinfo.gov/link/fr/42/37122","by":{"0":"12","1":"6, 20, 23, 38"}},{"t":"reg","label":"51 Fed. Reg. 41,206","url":"https://www.govinfo.gov/link/fr/51/41206","by":{"0":"12","1":"7"}},{"t":"reg","label":"61 Fed. Reg. 65,874","url":"https://www.govinfo.gov/link/fr/61/65874","by":{"0":"51"}},{"t":"reg","label":"65 Fed. Reg. 12,818","url":"https://www.govinfo.gov/link/fr/65/12818","by":{"0":"12"}},{"t":"reg","label":"86 Fed. Reg. 69,372","url":"https://www.govinfo.gov/link/fr/86/69372","by":{"0":"5, 12","1":"passim"}},{"t":"case","label":"Bickett, The Illusion of Substance: Why Rapanos v. United States and Its Resulting Regulatory Guidance Do Not Significantly Limit Federal Regulation of Wetlands","cite":"86 N.C. L. Rev. 1032","y":2008,"url":"https://www.courtlistener.com/c/N.C.%20L.%20Rev./86/1032/","by":{"0":"47"}},{"t":"case","label":"Reply Brief for the United States, United States v. Riverside Bayview Homes, Inc.","cite":"1985 WL 669804","y":1985,"by":{"0":"13"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Hodel v. Virginia Surface Mining & Reclamation Ass’n","cite":"452 U.S. 264","y":1981,"id":"1980/79-1538","sc":1,"op":2,"sum":"In the context of a facial challenge, the Act is constitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"International Paper Co. v. Ouellette","cite":"479 U.S. 481","y":1987,"id":"1986/85-1233","sc":1,"op":3,"sum":"The Clean Water Act (Act) prohibits the discharge of effluents into navigable waters unless the point source has obtained a permit from the Environmental Protection Agency (EPA). The Act also allows the State in which the point source is located (the \"source State\") to impose more stringent discharge limitations than the federal ones, and even to administer its own permit program if certain requirements are met. In …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"sum":"The Court held that the Eleventh Circuit Court of Appeals was bound by Florida state law in considering a felony battery charge.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Scialabba v. Cuellar de Osorio","cite":"573 U.S. 41","y":2014,"id":"2013/12-930","sc":1,"sum":"The Court held that the Immigration and Nationality Act does not allow children who have submitted an application for a visa to keep their original application date if they \"aged out\" before it was processed.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Stenberg v. Carhart","cite":"530 U.S. 914","y":2000,"id":"1999/99-830","sc":1,"sum":"In a complicated 5-4 decision delivered by Justice Stephen G. Breyer, the Court held that \"Nebraska's statute criminalizing the performance of \"partial birth abortion[s]\" violates the U.S. Constitution, as interpreted in Casey and Roe.\" The sharply divided Court struck down the statute because it placed an undue burden on a woman's right to have an abortion and did not allow for exception in cases of threatened health. \"All those who perform abortion procedures using that method must fear prosecution, conviction, and imprisonment,\" that results in \"an undue burden upon a woman's right to make an abortion decision,\" wrote Justice Breyer for the Court.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"op":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22"}},{"t":"case","label":"United States v. Ashland Oil & Transp. Co.","cite":"504 F.2d 1317","y":1974,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/504/1317/","op":1,"by":{"1":"6"}},{"t":"case","label":"United States v. Pennsylvania Indus. Chem. Corp.","cite":"411 U.S. 655","y":1973,"id":"1972/72-624","sc":1,"sum":"After the District Court refused respondent's offers of proof of reliance on Army Corps of Engineers regulations limiting violations to those impeding navigation, respondent was convicted of violating § 13 of the Rivers and Harbors Act of 1899 by discharging industrial pollutants into a navigable river. The Court of Appeals reversed on the ground that § 13 did not apply absent formalized permit procedures or, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4"}},{"t":"const","label":"Article I","by":{"1":"38"}},{"t":"usc","label":"33 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/33/1252","subs":["(a)"],"by":{"1":"34"}},{"t":"usc","label":"33 U.S.C. § 1313","url":"https://www.law.cornell.edu/uscode/text/33/1313","by":{"1":"2"}},{"t":"usc","label":"33 U.S.C. § 1321","url":"https://www.law.cornell.edu/uscode/text/33/1321","stext":{"head":"§1321. Oil and hazardous substance liability","paras":[[0,"(a) Definitions"],[0,"For the purpose of this section, the term—"],[1,"(1) \"oil\" means oil of any kind or in any form, including, but not limited to, petroleum, fuel oil, sludge, oil refuse, and oil mixed with wastes other than dredged spoil;"],[1,"(2) \"discharge\" includes, but is not limited to, any spilling, leaking, pumping, pouring, emitting, emptying or dumping, but excludes (A) discharges in compliance with a permit under section 1342 of this title, (B) discharges resulting from circumstances identified and reviewed and made a part of the public record with respect to a permit issued or modified under section 1342 of this title, and subject to a condition in such permit,,1 (C) continuous or anticipated intermittent discharges from a point source, identified in a permit or permit application under section 1342 of this title, which are caused by events occurring within the scope of relevant operating or treatment systems, and (D) discharges incidental to mechanical removal authorized by the President under subsection (c) of this section;"],[1,"(3) \"vessel\" means every description of watercraft or other artificial contrivance used, or capable of being used, as a means of transportation on water other than a public vessel;"],[1,"(4) \"public vessel\" means a vessel owned or bareboat-chartered and operated by the United States, or by a State or political subdivision thereof, or by a foreign nation, except when such vessel is engaged in commerce;"],[1,"(5) \"United States\" means the States, the District of Columbia, the Commonwealth of Puerto Rico, the Commonwealth of the Northern Mariana Islands, Guam, American Samoa, the Virgin Islands, and the Trust Territory of the Pacific Islands;"],[1,"(6) \"owner or operator\" means (A) in the case of a vessel, any person owning, operating, or chartering by demise, such vessel, and (B) in the case of an onshore facility, and an offshore facility, any person owning or operating such onshore facility or offshore facility, and (C) in the case of any abandoned offshore facility, the person who owned or operated such facility immediately prior to such abandonment;"],[1,"(7) \"person\" includes an individual, firm, corporation, association, and a partnership;"],[1,"(8) \"remove\" or \"removal\" refers to containment and removal of the oil or hazardous substances from the water and shorelines or the taking of such other actions as may be necessary to prevent, minimize, or mitigate damage to the public health or welfare, including, but not limited to, fish, shellfish, wildlife, and public and private property, shorelines, and beaches;"],[1,"(9) \"contiguous zone\" means the entire zone established or to be established by the United States under article 24 of the Convention on the Territorial Sea and the Contiguous Zone;"],[1,"(10) \"onshore facility\" means any facility (including, but not limited to, motor vehicles and rolling stock) of any kind located in, on, or under, any land within the United States other than submerged land;"],[1,"(11) \"offshore facility\" means any facility of any kind located in, on, or under, any of the navigable waters of the United States, any facility of any kind which is subject to the jurisdiction of the United States and is located in, on, or under any other waters, other than a vessel or a public vessel, and, for the purposes of applying subsections (b), (c), (e), and (o), any foreign offshore unit (as defined in section 1001 of the Oil Pollution Act 2) or any other facility located seaward of the exclusive economic zone;"],[1,"(12) \"act of God\" means an act occasioned by an unanticipated grave natural disaster;"],[1,"(13) \"barrel\" means 42 United States gallons at 60 degrees Fahrenheit;"],[1,"(14) \"hazardous substance\" means any substance designated pursuant to subsection (b)(2) of this section;"],[1,"(15) \"inland oil barge\" means a non-self-propelled vessel carrying oil in bulk as cargo and certificated to operate only in the inland waters of the United States, while operating in such waters;"],[1,"(16) \"inland waters of the United States\" means those waters of the United States lying inside the baseline from which the territorial sea is measured and those waters outside such baseline which are a part of the Gulf Intracoastal Waterway;"],[1,"(17) \"otherwise subject to the jurisdiction of the United States\" means subject to the jurisdiction of the United States by virtue of United States citizenship, United States vessel documentation or numbering, or as provided for by international agreement to which the United States is a party;"],[1,"(18) \"Area Committee\" means an Area Committee established under subsection (j);"],[1,"(19) \"Area Contingency Plan\" means an Area Contingency Plan prepared under subsection (j);"],[1,"(20) \"Coast Guard District Response Group\" means a Coast Guard District Response Group established under subsection (j);"],[1,"(21) \"Federal On-Scene Coordinator\" means a Federal On-Scene Coordinator designated in the National Contingency Plan;"],[1,"(22) \"National Contingency Plan\" means the National Contingency Plan prepared and published under subsection (d);"],[1,"(23) \"National Response Unit\" means the National Response Unit established under subsection (j);"],[1,"(24) \"worst case discharge\" means—"],[2,"(A) in the case of a vessel, a discharge in adverse weather conditions of its entire cargo; and"],[2,"(B) in the case of an offshore facility or onshore facility, the largest foreseeable discharge in adverse weather conditions;"],[1,"(25) \"removal costs\" means—"],[2,"(A) the costs of removal of oil or a hazardous substance that are incurred after it is discharged; and"],[2,"(B) in any case in which there is a substantial threat of a discharge of oil or a hazardous substance, the costs to prevent, minimize, or mitigate that threat;"],[1,"(26) \"nontank vessel\" means a self-propelled vessel that—"],[2,"(A) is at least 400 gross tons as measured under section 14302 of title 46 or, for vessels not measured under that section, as measured under section 14502 of that title;"],[2,"(B) is not a tank vessel;"],[2,"(C) carries oil of any kind as fuel for main propulsion; and"],[2,"(D) operates on the navigable waters of the United States, as defined in section 2101(23) of that title;"],[1,"(27) the term \"best available science\" means science that—"],[2,"(A) maximizes the quality, objectivity, and integrity of information, including statistical information;"],[2,"(B) uses peer-reviewed and publicly available data; and"],[2,"(C) clearly documents and communicates risks and uncertainties in the scientific basis for such projects;"],[1,"(28) the term \"Chairperson\" means the Chairperson of the Council;"],[1,"(29) the term \"coastal political subdivision\" means any local political jurisdiction that is immediately below the State level of government, including a county, parish, or borough, with a coastline that is contiguous with any portion of the United States Gulf of Mexico;"],[1,"(30) the term \"Comprehensive Plan\" means the comprehensive plan developed by the Council pursuant to subsection (t);"],[1,"(31) the term \"Council\" means the Gulf Coast Ecosystem Restoration Council established pursuant to subsection (t);"],[1,"(32) the term \"Deepwater Horizon oil spill\" means the blowout and explosion of the mobile offshore drilling unit Deepwater Horizon that occurred on April 20, 2010, and resulting hydrocarbon releases into the environment;"],[1,"(33) the term \"Gulf Coast region\" means—"],[2,"(A) in the Gulf Coast States, the coastal zones (as that term is defined in section 1453 of title 16),1 except that, in this section, the term \"coastal zones\" includes land within the coastal zones that is held in trust by, or the use of which is by law subject solely to the discretion of, the Federal Government or officers or agents of the Federal Government)) 1 that border the Gulf of Mexico;"],[2,"(B) any adjacent land, water, and watersheds, that are within 25 miles of the coastal zones described in subparagraph (A) of the Gulf Coast States; and"],[2,"(C) all Federal waters in the Gulf of Mexico;"],[1,"(34) the term \"Gulf Coast State\" means any of the States of Alabama, Florida, Louisiana, Mississippi, and Texas; and"],[1,"(35) the term \"Trust Fund\" means the Gulf Coast Restoration Trust Fund established pursuant to section 1602 of the Resources and Ecosystems Sustainability, Tourist Opportunities, and Revived Economies of the Gulf Coast States Act of 2012."],[0,"(b) Congressional declaration of policy against discharges of oil or hazardous substances; designation of hazardous substances; study of higher standard of care incentives and report to Congress; liability; penalties; civil actions: penalty limitations, separate offenses, jurisdiction, mitigation of damages and costs, recovery of removal costs, alternative remedies, and withholding clearance of vessels"],[0,"(1) The Congress hereby declares that it is the policy of the United States that there should be no discharges of oil or hazardous substances into or upon the navigable waters of the United States, adjoining shorelines, or into or upon the waters of the contiguous zone, or in connection with activities under the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.] or the Deepwater Port Act of 1974 [33 U.S.C. 1501 et seq.], or which may affect natural resources belonging to, appertaining to, or under the exclusive management authority of the United States (including resources under the Magnuson-Stevens Fishery Conservation and Management Act [16 U.S.C. 1801 et seq.])."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1321?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1321. Oil and hazardous substance liability","tname":"Navigation and Navigable Waters","by":{"1":"2"}},{"t":"usc","label":"33 U.S.C. § 1361","url":"https://www.law.cornell.edu/uscode/text/33/1361","by":{"1":"38"}},{"t":"usc","label":"33 U.S.C. § 1377","url":"https://www.law.cornell.edu/uscode/text/33/1377","subs":["(e)"],"by":{"1":"5, 7, 21"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"1":"36"}},{"t":"reg","label":"40 Fed. Reg. 31,320","url":"https://www.govinfo.gov/link/fr/40/31320","by":{"1":"6"}},{"t":"reg","label":"80 Fed. Reg. 37,054","url":"https://www.govinfo.gov/link/fr/80/37054","by":{"1":"12, 35, 43"}},{"t":"reg","label":"84 Fed. Reg. 56,626","url":"https://www.govinfo.gov/link/fr/84/56626","by":{"1":"13"}},{"t":"reg","label":"85 Fed. Reg. 22,250","url":"https://www.govinfo.gov/link/fr/85/22250","by":{"1":"3, 13, 31"}},{"t":"case","label":"Boechler, P.C. v. Comm’r","cite":"142 S. Ct. 1493","y":2022,"id":"2021/20-1472","sc":1,"sum":"The 30-day time limit to file a petition for review of a collection due process determination, 26 U. S. C. §6330(d)(1), is a nonjurisdictional deadline subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"7"}},{"t":"case","label":"Director v. Newport News Shipbuilding & Dry Dock Co.","cite":"514 U.S. 122","y":1995,"id":"1994/93-1783","sc":1,"op":2,"sum":"The Director is not \"adversely affected or aggrieved\" under §921(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Defense","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"2":"19, 23"}},{"t":"case","label":"Orchard Hill Bldg. Co. v. U.S. Army Corps of Eng’rs","cite":"893 F.3d 1017","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/893/1017/","by":{"2":"20"}},{"t":"case","label":"United States v. Chevron Pipe Line Co.","cite":"437 F. Supp. 2d 605","y":2006,"court":"N.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/437/605/","by":{"2":"20"}},{"t":"usc","label":"33 U.S.C. § 1160","url":"https://www.law.cornell.edu/uscode/text/33/1160","subs":["(a)(1970)","(c)(5)(1970)"],"op":2,"tname":"Navigation and Navigable Waters","by":{"2":"17, 17"}},{"t":"usc","label":"46 U.S.C. § 1451","url":"https://www.law.cornell.edu/uscode/text/46/1451","subs":["(1982)"],"by":{"2":"16"}},{"t":"law","label":"Pub. L. No. 92-75","url":"https://www.govinfo.gov/link/statute/85/213","by":{"2":"15-16"}},{"t":"usc","label":"42 U.S.C. § 4341","url":"https://www.law.cornell.edu/uscode/text/42/4341","subs":["(1970)"],"by":{"2":"4-5"}},{"t":"law","label":"Pub. L. No. 94-531","url":"https://www.govinfo.gov/link/statute/90/2489","by":{"2":"16"}},{"t":"law","label":"Pub. L. No. 98-89","url":"https://www.govinfo.gov/link/statute/97/500","by":{"2":"16"}},{"t":"usc","label":"16 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/16/1301","by":{"2":"4"}}]};